courier := &model.Courier{
		ID:     courierDB.ID,
		Name:   courierDB.Name,
		Phone:  courierDB.Phone,
		Status: courierDB.Status,
	}

func main() {
	if err := godotenv.Load(); err != nil {
		log.Printf("warn: .env not loaded: %v", err)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	db := initDBPool(ctx)
	defer db.Close()
	log.Println("postgres connected")

	courierRepo := repository.NewCourierRepository(db)
	courierUC := usecase.NewCourierUseCase(courierRepo)
	courierCtrl := handlers.NewCourierController(courierUC)

	srv := &http.Server{
		Addr:         ":" + resolvePort(),
		Handler:      initRouter(courierCtrl),
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	go gracefulShutdown(srv)

	log.Printf("service-courier listening on %s\n", srv.Addr)
	if err := srv.ListenAndServe(); !errors.Is(err, http.ErrServerClosed) {
		log.Fatalf("server start error: %v\n", err)
	}
}

type courierUseCase interface {
	GetCourier(ctx context.Context, id int) (*model.Courier, error)
	GetCouriers(ctx context.Context) ([]model.Courier, error)
	CreateCourier(ctx context.Context, req *dto.CourierCreateRequest) (int, error)
	UpdateCourier(ctx context.Context, req *dto.CourierUpdateRequest) error
}

type courierRepository interface {
	GetOneByID(ctx context.Context, id int) (*entity.Courier, error)
	GetAll(ctx context.Context) ([]entity.Courier, error)
	Create(ctx context.Context, courier *entity.Courier) (int, error)
	Update(ctx context.Context, courier *entity.Courier) error
}

type CourierController struct {
	useCase courierUseCase
}

func NewCourierController(useCase courierUseCase) *CourierController {
	return &CourierController{useCase: useCase}
}

